-- gop export --format sql (gop.graph/v2)
-- This file lists attack paths (who can make code run where). Keep it and the database private.
-- Load: sqlite3 gop.db < gop.sql   or   duckdb gop.duckdb < gop.sql
-- Idempotent: loading a run again replaces its rows; other runs are kept.
-- run_id: 2026-01-01T00:00:00Z/3e01a522d875
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS runs (run_id TEXT NOT NULL, enterprise TEXT NOT NULL, collected_at TEXT NOT NULL, schema_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nodes (run_id TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL, name TEXT NOT NULL, org TEXT, repo TEXT, evidence TEXT, declared INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS nodes_run_id_id ON nodes (run_id, id);
CREATE INDEX IF NOT EXISTS nodes_run_id_kind ON nodes (run_id, kind);
CREATE TABLE IF NOT EXISTS node_attrs (run_id TEXT NOT NULL, node_id TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, evidence TEXT);
CREATE INDEX IF NOT EXISTS node_attrs_run_id_node_id ON node_attrs (run_id, node_id);
CREATE INDEX IF NOT EXISTS node_attrs_run_id_key ON node_attrs (run_id, key);
CREATE TABLE IF NOT EXISTS edges (run_id TEXT NOT NULL, edge_id INTEGER NOT NULL, src TEXT NOT NULL, dst TEXT NOT NULL, label TEXT NOT NULL, evidence TEXT NOT NULL, confirmed INTEGER NOT NULL, source_api TEXT NOT NULL, observed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS edges_run_id_src ON edges (run_id, src);
CREATE INDEX IF NOT EXISTS edges_run_id_dst ON edges (run_id, dst);
CREATE TABLE IF NOT EXISTS edge_attrs (run_id TEXT NOT NULL, edge_id INTEGER NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS edge_attrs_run_id_edge_id ON edge_attrs (run_id, edge_id);
CREATE TABLE IF NOT EXISTS findings (run_id TEXT NOT NULL, rule TEXT NOT NULL, subject TEXT NOT NULL, severity REAL NOT NULL, possible REAL NOT NULL);
CREATE INDEX IF NOT EXISTS findings_run_id_rule ON findings (run_id, rule);
CREATE TABLE IF NOT EXISTS reach (run_id TEXT NOT NULL, principal TEXT NOT NULL, target TEXT NOT NULL, target_kind TEXT NOT NULL, confirmed INTEGER NOT NULL, evidence TEXT NOT NULL, hops INTEGER NOT NULL, path TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reach_run_id_principal ON reach (run_id, principal);
CREATE INDEX IF NOT EXISTS reach_run_id_target ON reach (run_id, target);
CREATE VIEW IF NOT EXISTS org_settings AS SELECT n.run_id AS run_id, n.id AS org, COALESCE(MAX(CASE WHEN a.key = 'sso' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS sso, COALESCE(MAX(CASE WHEN a.key = 'two_factor' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS two_factor, COALESCE(MAX(CASE WHEN a.key = 'ip_allow_list' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS ip_allow_list, COALESCE(MAX(CASE WHEN a.key = 'ip_allow_list_entries' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS ip_allow_list_entries, COALESCE(MAX(CASE WHEN a.key = 'ip_allow_list_apps' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS ip_allow_list_apps, COALESCE(MAX(CASE WHEN a.key = 'default_perm' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS default_perm, COALESCE(MAX(CASE WHEN a.key = 'members_create' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS members_create, COALESCE(MAX(CASE WHEN a.key = 'change_visibility' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS change_visibility, COALESCE(MAX(CASE WHEN a.key = 'delete_repos' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS delete_repos, COALESCE(MAX(CASE WHEN a.key = 'private_forks' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS private_forks, COALESCE(MAX(CASE WHEN a.key = 'members' THEN CASE WHEN a.evidence = 'not_visible' OR a.value IN ('', 'unknown') THEN 'unknown' ELSE a.value END END), 'unknown') AS members FROM nodes n LEFT JOIN node_attrs a ON a.run_id = n.run_id AND a.node_id = n.id WHERE n.kind = 'org' AND n.declared = 1 GROUP BY n.run_id, n.id;
DELETE FROM reach WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
DELETE FROM findings WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
DELETE FROM edge_attrs WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
DELETE FROM edges WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
DELETE FROM node_attrs WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
DELETE FROM nodes WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
DELETE FROM runs WHERE run_id = '2026-01-01T00:00:00Z/3e01a522d875';
COMMIT;
